/* Shared place catalog for both endpoints; coordinates from the official map. */
const previousSetZoom=setZoom;setZoom=function(value){previousSetZoom(value);document.body.classList.toggle('full-plan',zoom===100);};
const mapParams=new URLSearchParams(location.search),places=new Map();
const floorText=f=>f===1?'planta baja':'planta alta';
function addPlace(value,label,group,loc){if(loc?.coord)places.set(value,{...loc,value,label,group});}
for(const option of routeDestination.querySelectorAll('optgroup[label="Salones"] option'))addPlace(option.value,option.textContent,'Salones',getRoomDestination(option.value.slice(2)));
for(const [id,a] of Object.entries(routeAliases))if(id.startsWith('area-')&&a.kind==='room')addPlace('alias:'+id,a.label,'Servicios',getRoomDestination(a.target));
addPlace('entry','Entrada','Servicios',routeOriginOptions.find(o=>o.value==='o:entry'));
for(const o of routeOriginOptions.filter(o=>o.value.startsWith('o:zona')))addPlace(o.value,o.label,'Servicios',o);
bathroomTargets.forEach((b,i)=>addPlace('bath:'+i,'Baño '+(b.floor===1?'PB':'PA')+(i%2+1)+' · '+floorText(b.floor)+' · '+(i%2?'derecha':'izquierda')+' del plano','Baños',{floor:b.floor,coord:b.pin,bath:true,short:'Baño '+(b.floor===1?'PB':'PA')+(i%2+1)}));
posterTargets.forEach((p,i)=>addPlace('poster:'+i,'Pósters · punto '+(i+1)+' del plano','Servicios',p));
// A stand is anchored at the endpoint of the original approach route, not a made-up position.
for(const s of sponsors.filter(s=>s.placed&&s.stands?.length)){const path=routeToStandFromCoord(routeOriginOptions[0].coord,s.stands[0]);if(path?.length)addPlace('s:'+s.id,s.name+' · '+s.standSummary,'Stands',{floor:1,coord:path.at(-1)});}
const canonical=value=>value==='o:entry'?'entry':value?.startsWith('o:salon-')?'r:'+value.slice(2):value;
const oldOrigin=canonical(saved?.origin||routeOrigin.value),oldDestination=saved?.destination||routeDestination.value;
function fillPlaces(select,label){select.replaceChildren(new Option(label,''));for(const group of ['Salones','Servicios','Baños','Stands']){const g=document.createElement('optgroup');g.label=group;for(const p of places.values())if(p.group===group)g.append(new Option(p.label,p.value));select.append(g);}}
fillPlaces(routeOrigin,'Elige dónde estás');fillPlaces(routeDestination,'Elige adónde ir');
const originNote=document.createElement('p');originNote.className='origin-note';box.after(originNote);
const suggestedOrigin=canonical(mapParams.get('origin')),suggestedDestination=mapParams.get('next');
let originAssumed=false,lastEndpoint='destination';
routeOrigin.value=places.has(oldOrigin)?oldOrigin:'';routeDestination.value=places.has(oldDestination)?oldDestination:'';
if(!routeOrigin.value&&!saved?.manualOrigin&&places.has(suggestedOrigin)){routeOrigin.value=suggestedOrigin;originAssumed=true;}
if(saved?.originAssumed&&routeOrigin.value===suggestedOrigin)originAssumed=true;
const requestedPlace=mapParams.get('room');if(requestedPlace&&places.has('r:'+requestedPlace))routeDestination.value='r:'+requestedPlace;
if(!routeDestination.value&&places.has(suggestedDestination))routeDestination.value=suggestedDestination;
let manualOrigin=saved?.manualOrigin||false;
getOriginLoc=function(){return places.get(routeOrigin.value)||null;};
destinationInfo=function(){return places.get(routeDestination.value)||null;};
saveMapView=function(){try{sessionStorage.setItem(MAP_STATE_KEY,JSON.stringify({origin:routeOrigin.value,destination:routeDestination.value,floor:'both',zoom,drawn:hasRoute,originAssumed,manualOrigin}));}catch{}};
function refreshOriginNote(){originNote.textContent=originAssumed?'Origen sugerido por tu agenda · puedes cambiarlo.':'Origen elegido por ti · sin ubicación GPS.';originNote.hidden=!routeOrigin.value;}
function suggestion(side,value,time){if(!places.has(value))return;const p=places.get(value),button=document.createElement('button');button.type='button';button.className='endpoint-suggestion '+side;button.textContent=(side==='origin'?'Desde sugerido: ':'Hasta sugerido: ')+p.label.split(' · ')[0]+(time?' · '+time:'');button.title=side==='origin'?'Usar el salón de tu charla actual o reciente':'Ir al salón de tu próxima charla';button.addEventListener('click',()=>{if(side==='origin'){routeOrigin.value=value;originAssumed=true;manualOrigin=false;}else routeDestination.value=value;recalculate();});box.append(button);}
suggestion('origin',suggestedOrigin,mapParams.get('originTime'));suggestion('destination',suggestedDestination,mapParams.get('nextTime'));
routeOrigin.addEventListener('focus',()=>lastEndpoint='origin');routeDestination.addEventListener('focus',()=>lastEndpoint='destination');
routeOrigin.addEventListener('change',()=>{originAssumed=false;manualOrigin=true;refreshOriginNote();saveMapView();});
clearRouteBtn.addEventListener('click',()=>{manualOrigin=true;originAssumed=false;saveMapView();refreshOriginNote();});
const sourceSelectSponsor=selectSponsor;selectSponsor=function(id){sourceSelectSponsor(id);if(!places.has('s:'+id))return;for(const side of ['origin','destination']){const button=document.createElement('button');button.className='secondary';button.textContent=side==='origin'?'Salir desde este stand':'Ir a este stand';button.addEventListener('click',()=>{(side==='origin'?routeOrigin:routeDestination).value='s:'+id;if(side==='origin'){originAssumed=false;manualOrigin=true;}recalculate();box.scrollIntoView({block:'start'});});infoPanel.append(button);}};
function drawBathButtons(){document.querySelectorAll('.bath-place').forEach(e=>e.remove());for(const p of places.values())if(p.bath){const svg=document.querySelector('[data-map-floor="'+p.floor+'"] svg'),v=svg.viewBox.baseVal,button=document.createElement('button');button.className='bath-place'+(p.coord[0]/v.width<.06?' bath-edge-left':p.coord[0]/v.width>.94?' bath-edge-right':'');button.textContent=p.short;button.title=p.label;button.setAttribute('aria-label',p.label+' · elegir como origen o destino');button.style.left=(p.coord[0]/v.width*100)+'%';button.style.top=(p.coord[1]/v.height*100)+'%';button.addEventListener('click',()=>{(lastEndpoint==='origin'?routeOrigin:routeDestination).value=p.value;if(lastEndpoint==='origin'){originAssumed=false;manualOrigin=true;}recalculate();});svg.parentElement.append(button);}}
renderEndpoints=function(){document.querySelectorAll('.map-endpoint').forEach(e=>e.remove());const origin=getOriginLoc(),dest=destinationInfo(),same=origin&&dest&&origin.floor===dest.floor&&origin.coord.every((n,i)=>n===dest.coord[i]);if(same)placeEndpoint(origin.floor,origin.coord,'destination','Inicio y destino');else{if(origin)placeEndpoint(origin.floor,origin.coord,'origin',originAssumed?'Origen sugerido':'Desde aquí');if(dest)placeEndpoint(dest.floor,dest.coord,'destination',dest.bath?dest.short+' · Tu destino':'Tu destino');}drawBathButtons();};
renderGuide=function(){guide.replaceChildren();};
function frameMap(){const destinations=[...document.querySelectorAll('.map-endpoint.destination')];if(!destinations.length)return;let targetZoom=180;const frames=[];document.querySelectorAll('[data-map-floor]').forEach(card=>{const svg=card.querySelector('svg'),vb=svg.viewBox.baseVal,paths=[...svg.querySelectorAll('.route-line')];let points=[];for(const path of paths){const b=path.getBBox();points.push([b.x,b.y],[b.x+b.width,b.y+b.height]);}if(!points.length)for(const marker of card.querySelectorAll('.map-endpoint.destination'))points.push([parseFloat(marker.style.left)*vb.width/100,parseFloat(marker.style.top)*vb.height/100]);if(!points.length)return;const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),scroll=card.querySelector('.map-scroll');if(paths.length){targetZoom=Math.min(targetZoom,100*vb.width/Math.max(1,maxX-minX+110),100*scroll.clientHeight*vb.width/(Math.max(1,scroll.clientWidth)*(maxY-minY+80)));}frames.push({scroll,x:(minX+maxX)/2/vb.width,y:(minY+maxY)/2/vb.height});});
 setZoom(Math.floor(Math.max(100,Math.min(180,targetZoom))));requestAnimationFrame(()=>requestAnimationFrame(()=>{for(const f of frames){f.scroll.scrollLeft=f.x*f.scroll.scrollWidth-f.scroll.clientWidth/2;f.scroll.scrollTop=f.y*f.scroll.scrollHeight-f.scroll.clientHeight/2;}updateMapHeight();}));
}
recalculate=function(){clearRoute();guide.replaceChildren();const origin=getOriginLoc(),dest=destinationInfo();originChosen=!!origin;hasRoute=false;highlightRoom(routeDestination.value.startsWith('r:')?routeDestination.value.slice(2):null);
 if(origin&&dest){const same=origin.floor===dest.floor&&origin.coord.every((n,i)=>n===dest.coord[i]);let paths=[];if(!same){if(origin.floor===dest.floor)paths=[{floor:origin.floor,points:routeOnFloor(origin.floor,origin.coord,dest.coord)}];else{const upstairs=origin.floor===2?origin:dest;if(upstairs.stair){const side=upstairs.stair;paths=[{floor:origin.floor,points:routeOnFloor(origin.floor,origin.coord,(origin.floor===1?firstFloorStairs:secondFloorStairs)[side])},{floor:dest.floor,points:routeOnFloor(dest.floor,(dest.floor===1?firstFloorStairs:secondFloorStairs)[side],dest.coord)}];}}}
 const complete=paths.length&&paths.every(p=>p.points?.length>1);if(complete)paths.forEach(p=>drawPolyline(p.floor===1?routeLayer1:routeLayer2,p.points));hasRoute=!!complete;
 if(same)routeStatus.textContent='Origen y destino están en el mismo punto.';else if(!hasRoute)routeStatus.textContent='No tenemos un recorrido trazado entre estos puntos. Pregunta al personal del congreso.';else if(origin.floor!==dest.floor){const side=(origin.floor===2?origin:dest).stair;routeStatus.textContent=(origin.floor===1?'Sube a planta alta':'Baja a planta baja')+' por la escalera del '+(side==='left'?'lado izquierdo':'lado derecho')+' del plano.';}else routeStatus.textContent='Sigue el trazado en '+floorText(origin.floor)+'.';
 }else routeStatus.textContent=dest?'Destino marcado en '+floorText(dest.floor)+'. Elige desde dónde sales.':'Elige origen y destino en los selectores.';
 renderEndpoints();setFloor();document.querySelectorAll('[data-map-floor]').forEach(card=>card.classList.toggle('destination-floor',Number(card.dataset.mapFloor)===dest?.floor));clearRouteBtn.hidden=!origin;refreshOriginNote();frameMap();
};
recalculate();document.body.dataset.usabilityReady='true';
